"""z:widened-complete — the widened closure is generated by one exact stratum.

Theorem (Appendix B): let F0 be an obtuse superbase of G with conorms p0,
tau >= 0, lambda1(G) > 32 tau. Zero every conorm of F0 that is <= 4 tau;
this gives a positive-definite lattice L* whose exact closure G(L*) is
generated from F0 by relabellings and flips at its exact zeros. Then

    S_tau(G) = { F in G(L*), same integer coordinates : conorms_G(F) >= -tau }.

The proof has two inequalities with exact combinatorial constants, checked
here, and the theorem is compared with brute force. Lattices are given by
their conorm vectors in the frame of F0, so F0 is obtuse by construction.
"""
from __future__ import annotations

from sellingproofs.registry import claim  # noqa: E402

import itertools

import pytest

SL = [(0, 1), (0, 2), (0, 3), (1, 2), (1, 3), (2, 3)]
CUTS = [{0}, {1}, {2}, {3}, {0, 1}, {0, 2}, {0, 3}]
S0 = [[-1, -1, -1], [1, 0, 0], [0, 1, 0], [0, 0, 1]]


def _gram(p):
    import numpy as np
    return np.array([[p[0] + p[3] + p[4], -p[3], -p[4]],
                     [-p[3], p[1] + p[3] + p[5], -p[5]],
                     [-p[4], -p[5], p[2] + p[4] + p[5]]], float)


def _cn(S, G):
    import numpy as np
    S = np.asarray(S, float)
    return np.array([-S[i] @ G @ S[j] for i, j in SL])


def _key(S):
    a = tuple(sorted(tuple(int(round(x)) for x in v) for v in S))
    b = tuple(sorted(tuple(-int(round(x)) for x in v) for v in S))
    return min(a, b)


def _flip(S, i, j):
    k, l = [m for m in range(4) if m not in (i, j)]
    U = S.copy()
    U[i], U[k], U[l] = -S[i], S[i] + S[k], S[i] + S[l]
    return U


def _lam1(p):
    return min(sum(p[n] for n, (a, b) in enumerate(SL) if (a in A) != (b in A))
               for A in CUTS)


@pytest.fixture(scope="module")
def superbases():
    """every superbase with entries in [-2, 2] in the F0 frame (135,408)."""
    import numpy as np
    r = np.arange(-2, 3)
    M = np.array(np.meshgrid(*[r] * 9, indexing="ij")).reshape(9, -1).T.reshape(-1, 3, 3)
    B = M[np.abs(np.round(np.linalg.det(M))) == 1].astype(float)
    return np.concatenate([-(B.sum(1))[:, None, :], B], 1)


def _brute(SB, G, tau):
    import numpy as np
    P = -np.einsum("nia,ab,njb->nij", SB, G, SB)
    q = np.stack([P[:, i, j] for i, j in SL], 1)
    keep = q.min(1) >= -tau - 1e-9 * np.abs(G).max()
    return {_key(S) for S in SB[keep]}, SB[keep]


def _generate(p0, theta, tau):
    """exact closure of L* (zeros of p0 at <= theta) by flips at exact zeros,
    then the filter at -tau under the measured metric."""
    import numpy as np
    G, Gs = _gram(p0), _gram(np.where(np.asarray(p0) <= theta, 0.0, p0))
    tol = 1e-9 * np.abs(G).max()
    s0 = np.array(S0, float)
    seen, front = {_key(s0): s0}, [s0]
    while front:
        S = front.pop()
        p = _cn(S, Gs)
        for n, (i, j) in enumerate(SL):
            if abs(p[n]) < tol:
                U = _flip(S, i, j)
                k = _key(U)
                if k not in seen and _cn(U, Gs).min() >= -tol:
                    seen[k] = U
                    front.append(U)
    return {k for k, S in seen.items() if _cn(S, G).min() >= -tau - tol}, seen


@claim("z44", "SI Lemma S4.4", "SI Theorem S4.5", kind="exhaustive")
def test_combinatorial_constants():
    r"""The combinatorial constants of the band theorem: M = 4 and R = 8 over every connected graph on K4, the largest ratio 3 + 2 sqrt2, and the equality case."""
    import numpy as np
    from scipy.linalg import eigh

    def connected(es):
        adj = {v: set() for v in range(4)}
        for a, b in es:
            adj[a].add(b)
            adj[b].add(a)
        seen, st = {0}, [0]
        while st:
            x = st.pop()
            for y in adj[x] - seen:
                seen.add(y)
                st.append(y)
        return len(seen) == 4

    def inc(es):
        A = np.zeros((len(es), 3))
        for r_, (a, b) in enumerate(es):
            if a:
                A[r_, a - 1] += 1
            if b:
                A[r_, b - 1] -= 1
        return A

    box = 15
    K = np.array([(0,) + k for k in itertools.product(range(-box, box + 1), repeat=3)])
    classes = [np.array(s) for s in itertools.product((0, 1), repeat=4) if 0 < sum(s) < 4]
    M = R = 0.0
    rhos = []
    for r_ in range(3, 7):
        for Lg in itertools.combinations(SL, r_):
            if not connected(Lg):
                continue
            rest = [e for e in SL if e not in Lg]
            for nN in range(1, len(rest) + 1):
                for N in itertools.combinations(rest, nN):
                    AL, AN = inc(Lg), inc(N)
                    rho = eigh(AN.T @ AN, AL.T @ AL, eigvals_only=True).max()
                    rhos.append(rho)
                    # outside the box (max|k| > 15, so Q = sum_L dk^2 > 75) the ratio
                    # is < 8: sum_N gamma <= rho Q + sqrt(|N| rho Q),
                    # sum_L gamma >= Q - sqrt(|L| Q)
                    for Q in np.geomspace(box ** 2 / 3, 1e9, 300):
                        assert rho * Q + (len(N) * rho * Q) ** 0.5 < 8 * (Q - (len(Lg) * Q) ** 0.5)
                    for s in classes:
                        def gam(e):
                            dk = K[:, e[0]] - K[:, e[1]]
                            return dk * (dk + s[e[0]] - s[e[1]])
                        gL = sum(gam(e) for e in Lg)
                        gN = sum(gam(e) for e in N)
                        M = max(M, gN[gL == 0].max())
                        R = max(R, (gN[gL > 0] / gL[gL > 0]).max())
    assert M == 4
    assert R == 8
    assert abs(max(rhos) - (3 + 2 * 2 ** 0.5)) < 1e-9


LATTICES = {   # conorm vectors in the F0 frame; small entries play the noisy walls
    "mP two walls": (847.65, 1600.0, 2447.65, 0.0, 52.35, 0.0),
    "oP three walls": (900.0, 1600.0, 2500.0, 0.0, 0.0, 0.0),
    "cP": (900.0, 900.0, 900.0, 0.0, 0.0, 0.0),
    "hP": (450.0, 450.0, 2500.0, 450.0, 0.0, 0.0),
    "cI six ties": (300.0,) * 6,
    "aP generic": (310.0, 520.0, 700.0, 95.0, 160.0, 240.0),
    "plate": (400.0, 400.0, 10000.0, 0.0, 0.0, 0.0),
    "needle": (1747.0, 1747.0, 54289.0, 1747.0, 0.0, 0.0),
}


def _cases():
    import numpy as np
    rnd = np.random.default_rng(44)
    out = []
    for name, base in LATTICES.items():
        base = np.array(base, float)
        lam = _lam1(base)
        for frac in (0.1, 0.5, 0.99):
            tau = frac * lam / 32
            for _ in range(3):
                # every wall moves to a random value in [0, 6 tau]: some below tau,
                # some in the grey zone (tau, 4 tau], some above
                p = base.copy()
                walls = p < 1e-12
                p[walls] = rnd.uniform(0, 6 * tau, walls.sum())
                p[~walls] *= np.exp(rnd.normal(0, 1e-3, (~walls).sum()))
                if _lam1(p) > 32 * tau:
                    out.append((name, frac, p, tau))
    return out


@claim("z44", "main Lemma A1", "SI Lemmas S4.2, S4.3", kind="exhaustive")
def test_class_gap_and_excess_bound(superbases):
    r"""On every brute-force near-obtuse frame, the class excess is at most 16 tau, and a frame outside the closure has some class excess of at least 4 m* with m* > 4 tau."""
    import numpy as np
    parts = [np.array(s) for s in itertools.product((0, 1), repeat=4) if 0 < sum(s) < 4 and s[0] == 0]
    for name, frac, p, tau in _cases()[::3]:
        G = _gram(p)
        _, F = _brute(superbases, G, tau)
        gen, _ = _generate(p, 4 * tau, tau)
        mstar = p[p > 4 * tau].min()
        assert mstar > 4 * tau
        # class minima = F0 partial sums (F0 obtuse for G)
        s0 = np.array(S0, float)
        mu = {tuple(s): float((s @ s0) @ G @ (s @ s0)) for s in parts}
        for S in F:
            ex = []
            for s in parts:
                w = s @ S
                # the class of w is read from its F0 coordinates mod 2
                c = np.round(np.linalg.solve(s0[1:4].T, w)).astype(int) % 2
                cs = np.array([0, *c])
                cs = cs if cs[0] == 0 else 1 - cs
                ex.append(float(w @ G @ w) - mu[tuple(cs)])
            assert max(ex) <= 16 * tau + 1e-6 * np.abs(G).max(), name
            if _key(S) not in gen:
                assert max(ex) >= 4 * mstar - 1e-6 * np.abs(G).max(), name


@claim("z44", "SI Theorem S4.5", kind="exhaustive")
def test_generated_equals_brute_force(superbases):
    r"""Zeroing at 4 tau, generating by exact flips and filtering at -tau gives the brute-force widened set in every case up to tau = 0.99 lambda1/32, grey-zone walls included."""
    for name, frac, p, tau in _cases():
        truth, _ = _brute(superbases, _gram(p), tau)
        gen, _ = _generate(p, 4 * tau, tau)
        assert gen == truth, (name, frac)


@claim("z44", "SI §S4", kind="exhaustive")
def test_grey_zone_needs_the_4tau_threshold(superbases):
    r"""Zeroing only at tau misses a member when a wall y lies in (tau, 2 tau] beside a wall z < tau with y - z <= tau; zeroing at 4 tau is exact."""
    import numpy as np
    for name in ("oP three walls", "cP", "plate"):
        p = np.array(LATTICES[name], float)
        tau = 0.1 * _lam1(p) / 32
        walls = np.where(p < 1e-12)[0]
        p[walls[0]], p[walls[1]] = 1.2 * tau, 0.5 * tau
        truth, _ = _brute(superbases, _gram(p), tau)
        at_tau, _ = _generate(p, tau, tau)
        at_4tau, _ = _generate(p, 4 * tau, tau)
        assert len(truth) == 7 and len(at_tau) == 6 and at_tau < truth
        assert at_4tau == truth


@claim("z44", "SI §S4", kind="exhaustive")
def test_worked_pair_beyond_the_hypothesis(superbases):
    r"""For the worked cell lambda1/32 = 28.2, below the band tau = 43.2 used; the construction is still exact there and at tau = 60."""
    import numpy as np
    from agentsg.cell.canonical import canonical_superbase
    from agentsg.cell.metric import UnitCell
    D = (30.02, 39.97, 50.03, 90.25, 92.05, 89.80)
    G = np.array(UnitCell(*D).metric_tensor())
    p0 = _cn(np.array(canonical_superbase(D)[0], float), G)
    assert abs(_lam1(p0) / 32 - 28.2) < 0.1
    for tau, n in ((43.2, 6), (60.0, 14)):
        truth, _ = _brute(superbases, _gram(p0), tau)
        gen, _ = _generate(p0, 4 * tau, tau)
        assert gen == truth and len(truth) == n
